<script>
 // Render every API timestamp in Indian Standard Time, regardless of browser timezone.
 // Historical values without a timezone are interpreted as UTC (older Sheets exports).
 function formatIST(value) {
  if (!value) return '—';
  const raw=String(value).trim();
  const iso=raw.includes('T') ? raw : raw.replace(' ', 'T');
  const aware=/([zZ]|[+-]\d{2}:?\d{2})$/.test(iso) ? iso : iso+'Z';
  const date=new Date(aware);
  if(Number.isNaN(date.getTime())) return raw;
  return new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).format(date)+' IST';
 }
 import { onMount } from 'svelte';
 import { LayoutDashboard, ChartNoAxesColumn, FilePlus2, FileText, Search, RefreshCw, Download, X, LogOut, ArrowRight, ArrowLeft, Eye, EyeOff, LockKeyhole, Mail, ShieldCheck, AlertCircle, CheckCircle2 } from 'lucide-svelte';
 let mcubeUsername=$state(''), mcubePassword=$state(''), mcubeCredentialConfigured=$state(false), mcubeCredentialBusy=$state(false), mcubeCredentialMessage=$state('');
 let role=$state('operator'), settings=$state({}), settingsVersion=$state(''), requests=$state([]), notifications=$state([]), saving=$state(false), requestBusy=$state(false), chosenRequests=$state([]), reviewReason=$state('Reviewed previous replacement'), employeeSyncBusy=$state(false);
 let reviewTarget=$state(null), reviewDecision=$state(null), requestConfirm=$state(false); let token=$state(sessionStorage.getItem('did_token')||''); let sessionExpiredMessage=$state(''); let loginEmail=$state(''); let loginPin=$state(''); let loginOtp=$state(''); let challengeId=$state(''); let loginBusy=$state(false); let loginError=$state(''); let showLoginPin=$state(false);
 let dids=$state([]), query=$state(''), type=$state('active'), assignment=$state('all'), operator=$state('all');
 let tab=$state('Dashboard'), selected=$state(null), busy=$state(false), loading=$state(false), error=$state(''), notice=$state(''), configured=$state(false);
 let inventoryStatus=$state(null), initialSyncBusy=$state(false), settingsLoaded=$state(false), settingsDirty=$state(false);
 let settingsSection=$state('intake');
 let insights=$state(null), insightsBusy=$state(false), insightsError=$state(''), reportSearch=$state('');
 let selectedDids=$state([]), confirmBatch=$state(false), operationResults=$state([]), batch=$state(null), batchBusy=$state(false), batchError=$state(''), queueItems=$state([]), currentQueueId=$state('');
 let inventoryPageSize=$state(50), requestPage=$state(1), requestPageSize=$state(25), requestSearch=$state(''), requestStatus=$state('all'), analyticsMonth=$state('all'), analyticsSearch=$state(''), analyticsPage=$state(1), analyticsPageSize=$state(25), profileOpen=$state(false);
 let date=$state(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())); let replacement=$state(''); let page=$state(1); 
 let requestFiltered=$derived(requests.filter(r=>(requestStatus==='all'||r.status===requestStatus)&&`${r.agent_name||''} ${r.agent_number||''} ${r.current_did||''} ${r.status||''}`.toLowerCase().includes(requestSearch.trim().toLowerCase())));
 let requestVisible=$derived(requestFiltered.slice((requestPage-1)*requestPageSize,requestPage*requestPageSize));
 let monthOptions=$derived(insights?.monthly?.map(x=>x.month)||[]);
 let monthlyAgents=$derived((insights?.monthly||[]).filter(x=>(analyticsMonth==='all'||x.month===analyticsMonth)&&`${x.agent_name||''} ${x.agent_number||''} ${x.manager||''} ${x.team_lead||''}`.toLowerCase().includes(analyticsSearch.trim().toLowerCase())));
 let normalizedQuery=$derived(query.trim().toLowerCase());
 let filtered=$derived(dids.filter(d=>(type==='all'||d.status===type)&&(type!=='active'||assignment==='all'||(assignment==='assigned'?!!d.agent_number:!d.agent_number))&&(type!=='active'||operator==='all'||d.operator===operator)&&`${d.did} ${d.agent||''} ${d.agent_number||''} ${d.operator||''}`.toLowerCase().includes(normalizedQuery)));
 let pageItems=$derived(filtered.slice((page-1)*inventoryPageSize,page*inventoryPageSize));
 let operators=$derived([...new Set(dids.map(d=>d.operator).filter(Boolean))].sort());
 let pool=$derived(dids.filter(d=>d.status==='pool'));
 let active=$derived(dids.filter(d=>d.status==='active'));
 let counsellors=$derived(active.filter(d=>d.agent_number && d.agent?.toLowerCase()!=='common pool').length);
 let activeCommonPool=$derived(active.filter(d=>!d.agent_number || d.agent?.toLowerCase()==='common pool').length);
 let categoryItems=$derived(dids.filter(d=>type==='all'||d.status===type));
 let duplicateCount=$derived(filtered.filter(d=>d.duplicate).length);
 let duplicateGroups=$derived(Object.entries(Object.groupBy(dids.filter(d=>d.duplicate),d=>`${d.status}:${d.did}`)).map(([key,rows])=>({key,did:rows[0].did,status:rows[0].status,count:rows.length,agents:[...new Set(rows.map(x=>x.agent).filter(Boolean))].join(', ')})).sort((a,b)=>a.status.localeCompare(b.status)||a.did.localeCompare(b.did)));
 let showDuplicates=$state(false);
 let proposed=$derived(pool.find(d=>d.did===replacement));
 let selectable=$derived(filtered.filter(d=>d.status==='active'&&d.agent_number&&!d.duplicate&&d.agent?.toLowerCase()!=='common pool'));
 let allPageSelected=$derived(pageItems.filter(d=>d.agent_number&&!d.duplicate&&d.agent?.toLowerCase()!=='common pool').every(d=>selectedDids.includes(d.did)) && pageItems.some(d=>d.agent_number&&!d.duplicate));
 let batchPlan=$derived(selectedDids.map((did,i)=>({old:dids.find(d=>d.did===did),next:pool[i]})));
 function selectVisible(){const eligible=pageItems.filter(d=>d.status==='active'&&d.agent_number&&!d.duplicate&&d.agent?.toLowerCase()!=='common pool').map(d=>d.did);if(eligible.every(d=>selectedDids.includes(d)))selectedDids=selectedDids.filter(d=>!eligible.includes(d));else selectedDids=[...new Set([...selectedDids,...eligible])].slice(0,pool.length)}
 function selectAllEligible(){selectedDids=selectable.map(d=>d.did).slice(0,pool.length)}
 function openSingle(d){if(batchBusy)return;openAction(d,'reassign');replacement=pool[0]?.did||''}
 async function confirmSingle(){if(!selected||!replacement||busy||batchBusy)return;const d=selected;const expected=pool[0]?.did;if(replacement!==expected){error='The first available FIFO DID has changed. Refresh inventory and try again.';return}selected=null;await submitDids([d.did])}
 async function submitDids(didsToSubmit){if(batchBusy||!didsToSubmit.length)return;batchError='';operationResults=[];batchBusy=true;try{const x=await api('/api/reassign',{method:'POST',body:JSON.stringify({dids:didsToSubmit})});currentQueueId=x.queue_id;batch=x;await pollBatch()}catch(e){batchError=String(e.message);batchBusy=false}}
 
 function toggleDid(d){selectedDids=selectedDids.includes(d)?selectedDids.filter(x=>x!==d):[...selectedDids,d]}
 async function startBatch(){if(batchBusy||!selectedDids.length)return;confirmBatch=false;await submitDids([...selectedDids])}
 async function pollBatch(){while(token){try{const x=await api('/api/queue');const live=await api('/api/batch').catch(()=>null);if(live?.results)operationResults=live.results;queueItems=x.items||[];const mine=queueItems.find(q=>q.queue_id===currentQueueId);if(!mine||['completed','needs_reconciliation','cancelled'].includes(mine.status)){batchBusy=false;selectedDids=[];if(mine?.status==='needs_reconciliation')batchError='Operation needs administrator reconciliation';await refresh(false);return}batch={...mine,running:mine.status==='processing'};}catch(e){batchError='Unable to read queue. Check audit and recovery before retrying.';batchBusy=false;return}await new Promise(resolve=>setTimeout(resolve,3000))}}
 function sessionExpiry(tokenValue){
  try {
   const raw=tokenValue.split('.')[0].replace(/-/g,'+').replace(/_/g,'/');
   const payload=JSON.parse(atob(raw));
   return Number(payload.exp)*1000 || 0;
  } catch { return 0; }
 }
 function expireSession(){
  if(!token)return;
  sessionStorage.removeItem('did_token');
  token=''; dids=[]; selected=null; confirmBatch=false; selectedDids=[];
  settingsLoaded=false; loginPin=''; loginOtp=''; challengeId='';
  error=''; notice=''; sessionExpiredMessage='Your session expired. Please sign in again using PIN and OTP.';
  loginError=sessionExpiredMessage;
 }
 async function readApiResponse(response){
  // An expired session is an authentication problem, not an inventory or Sheets failure.
  if(response.status===401){expireSession();throw Error('Session expired. Sign in again.');}
  const raw=await response.text();let parsed;
  try{parsed=raw?JSON.parse(raw):{}}catch{
   throw Error(`Server returned HTTP ${response.status} instead of JSON. Check Render logs for the underlying error.`);
  }
  if(!response.ok){const detail=parsed?.detail;throw Error(typeof detail==='string'?detail:detail?.message||`Request failed (HTTP ${response.status})`)}
  return parsed;
 }
 async function api(path,opts={}){
  const currentToken=token;
  if(!currentToken)throw Error('Login required');
  const expires=sessionExpiry(currentToken);
  if(expires && Date.now()>=expires){expireSession();throw Error('Session expired. Sign in again.');}
  const r=await fetch(path,{...opts,headers:{Authorization:`Bearer ${currentToken}`,'Content-Type':'application/json',...(opts.headers||{})}});
  // Ignore stale 401s from an earlier session after a new login.
  if(r.status===401 && token!==currentToken)throw Error('Previous session expired');
  return readApiResponse(r);
 }
 async function loadRole(){try{role=(await api('/api/me')).role}catch(e){error=e.message}}
 async function loadMCubeCredentialStatus(){try{const x=await api('/api/mcube-config/credentials/status');mcubeCredentialConfigured=!!x.configured;}catch(e){mcubeCredentialMessage=e.message}}
 async function saveMCubeCredentials(){if(!mcubeUsername.trim()||!mcubePassword){mcubeCredentialMessage='Enter both MCube username and password.';return}mcubeCredentialBusy=true;mcubeCredentialMessage='';try{await api('/api/mcube-config/credentials',{method:'PUT',body:JSON.stringify({username:mcubeUsername.trim(),password:mcubePassword})});mcubePassword='';mcubeUsername='';mcubeCredentialConfigured=true;mcubeCredentialMessage='Credentials encrypted and saved. Test login before syncing calls.';}catch(e){mcubeCredentialMessage='Save failed: '+e.message}finally{mcubeCredentialBusy=false}}
 async function testMCubeCredentials(){mcubeCredentialBusy=true;mcubeCredentialMessage='';try{const x=await api('/api/mcube-config/credentials/test',{method:'POST'});mcubeCredentialMessage=x.message}catch(e){mcubeCredentialMessage='Login test failed: '+e.message}finally{mcubeCredentialBusy=false}}
 async function loadSettings(){error='';try{let x=await api('/api/settings');settings=x.settings;settingsVersion=x.version;settingsLoaded=true;settingsDirty=false;notice='Settings loaded from Google Sheets.'}catch(e){error='Settings could not be loaded: '+e.message}}
 async function saveSettings(){saving=true;error='';notice='';try{
  const x=await api('/api/settings',{method:'PUT',body:JSON.stringify({settings,version:settingsVersion})});
  const verified=await api('/api/settings');
  if(verified.version!==x.version)throw Error('Settings saved but read-back version differs. Reload and inspect Google Sheets.');
  settings=verified.settings;settingsVersion=verified.version;settingsDirty=false;
  notice=`Settings saved and verified in Google Sheets (${x.changed} changes).`;
 }catch(e){error=`Settings not confirmed: ${e.message}`;}finally{saving=false}}
 async function loadInsights(){insightsBusy=true;insightsError='';try{insights=await api('/api/insights')}catch(e){insightsError=e.message}finally{insightsBusy=false}}
 function downloadReport(rows,filename){if(!rows?.length)return;const cols=Object.keys(rows[0]);const lines=[cols.join(','),...rows.map(row=>cols.map(k=>'"'+String(row[k]??'').replaceAll('"','""')+'"').join(','))];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
 async function loadRequests(){let problems=[];try{requests=(await api('/api/requests')).items}catch(e){problems.push('Request queue: '+e.message)}try{notifications=(await api('/api/notifications')).items}catch(e){problems.push('Notification logs: '+e.message)}if(problems.length)error=problems.join(' | ');else error=''}
 async function autoSync(){try{await syncRequests();await runReminders()}catch(e){error=e.message}}
 async function syncRequests(){requestBusy=true;error='';try{let x=await api('/api/requests/sync',{method:'POST'});notice=`MCube fetched ${x.fetched} calls; imported ${x.created} new requests and ${x.repeated} repeat calls. ${x.ignored} skipped. ${x.ignored ? 'Reasons: '+Object.entries(x.skipped_reasons||{}).filter(([k,v])=>v>0).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(', ') : ''}`;await loadRequests()}catch(e){error=e.message}finally{requestBusy=false}}
 async function syncEmployees(){employeeSyncBusy=true;try{let x=await api('/api/employees/sync',{method:'POST'});notice=`Employee directory updated: ${x.count} agents.`}catch(e){error=e.message}finally{employeeSyncBusy=false}}
 async function runReminders(){requestBusy=true;try{let x=await api('/api/reminders/run',{method:'POST'});notice=x.disabled?'Reminders are disabled in Settings.':`Reminders: ${x.eligible||0} eligible; ${x.submitted||0} submitted, ${x.rejected||0} rejected, ${x.skipped||0} skipped, ${x.uncertain||0} uncertain. ${x.not_due||0} not due, ${x.max_attempts||0} at attempt limit, ${x.invalid_timestamp||0} invalid timestamps.`;await loadRequests()}catch(e){error=e.message}finally{requestBusy=false}}
 function openReview(r,approved){reviewTarget=r;reviewDecision=approved;reviewReason=approved?'Reviewed previous replacement':'Recent replacement – request declined'}
 async function confirmReview(){if(!reviewTarget||reviewDecision===null||!reviewReason.trim())return;requestBusy=true;try{await api(`/api/requests/${reviewTarget.request_id}/review`,{method:'POST',body:JSON.stringify({approved:reviewDecision,reason:reviewReason.trim()})});reviewTarget=null;reviewDecision=null;await loadRequests()}catch(e){error=e.message}finally{requestBusy=false}}
 async function replaceRequests(){if(!chosenRequests.length||batchBusy)return;requestConfirm=false;batchBusy=true;batchError='';try{let x=await api('/api/requests/reassign',{method:'POST',body:JSON.stringify({request_ids:chosenRequests})});batch=x;currentQueueId=x.queue_id;await pollBatch();chosenRequests=[];await loadRequests()}catch(e){batchError=e.message;batchBusy=false}}
 async function signin(){loginBusy=true;loginError='';try{const r=await fetch('/api/auth/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:loginEmail,pin:loginPin})});const x=await r.json();if(!r.ok)throw Error(x.detail||'Unable to send OTP');challengeId=x.challenge_id;loginPin=''}catch(e){loginError=e.message}finally{loginBusy=false}}
 async function verifyOtp(){const cleanOtp=String(loginOtp).replace(/\D/g,'').slice(0,6);loginOtp=cleanOtp;if(!/^[0-9]{6}$/.test(cleanOtp)){loginError='Please enter a valid 6-digit OTP.';return;}loginBusy=true;loginError='';try{const r=await fetch('/api/auth/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge_id:challengeId,otp:cleanOtp})});const x=await r.json();if(!r.ok)throw Error(x.detail||'OTP verification failed');token=x.token;sessionStorage.setItem('did_token',token);sessionExpiredMessage='';loginError='';loginOtp='';refresh();loadRole();loadRequests()}catch(e){loginError=e.message}finally{loginBusy=false}}
 function openTab(next){if(tab==='Settings' && next!=='Settings' && settingsDirty && !window.confirm('Settings have unsaved changes. Leave without saving?'))return;tab=next;if(next==='Analytics'||next==='Report')loadInsights();if(next==='Settings'){loadSettings();if(role==='admin')loadMCubeCredentialStatus()}}
 function signout(){sessionStorage.removeItem('did_token');token='';dids=[];selected=null;confirmBatch=false;selectedDids=[];error='';notice='';loginError='';challengeId='';}
 async function refresh(force=false){loading=true;error='';try{
  inventoryStatus=await api('/api/inventory/status');
  if(force){await api('/api/sync',{method:'POST'});}
  const data=await api('/api/dids');configured=!!data.configured;
  dids=(data.items||[]).map(d=>({...d,status:String(d.status||'unknown').toLowerCase()}));
  notice=force?`DID inventory refreshed (${dids.length} records).`:notice;
  if(force)inventoryStatus=await api('/api/inventory/status');
 }catch(e){error=`DID inventory could not be loaded: ${e.message}`;}finally{loading=false}}
 onMount(()=>{if(token && sessionExpiry(token) && Date.now()>=sessionExpiry(token))expireSession();if(token){refresh();loadRole();loadRequests();api('/api/queue').then(x=>{queueItems=x.items||[]}).catch(()=>{})}const expiryInterval=window.setInterval(()=>{if(token && sessionExpiry(token) && Date.now()>=sessionExpiry(token))expireSession()},15000);const handler=e=>{if(batchBusy){e.preventDefault();e.returnValue='A DID batch is in progress'}};const visibility=()=>{if(document.hidden&&batchBusy)notice='Bulk processing continues on the server. Return to this tab to monitor progress.'};window.addEventListener('beforeunload',handler);document.addEventListener('visibilitychange',visibility);return()=>{window.clearInterval(expiryInterval);window.removeEventListener('beforeunload',handler);document.removeEventListener('visibilitychange',visibility)}});
 function openAction(d,action){selected={...d,action};replacement='';date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
 async function initializeInventory(){initialSyncBusy=true;try{await refresh(true)}finally{initialSyncBusy=false}}
 function changeSetting(key,value){settings={...settings,[key]:value};settingsDirty=true;notice=''}
 async function execute(){if(!selected||busy)return;busy=true;error='';notice='';try{let data=await api(`/api/did/${selected.action}`,{method:'POST',body:JSON.stringify({did:selected.did,agent:selected.agent||null})});dids=dids.map(d=>d.did===selected.did?{...d,status:selected.action==='activate'?'active':'inactive'}:d);notice=`${selected.did}: ${selected.action} request accepted by MCube. Verify live status.`;selected=null;}catch(e){error=e.message}finally{busy=false}}
 function exportCSV(){let cols=type==='active'?['did','agent','agent_number','operator','status']:['did','operator','status'];let lines=[cols.join(','),...filtered.map(d=>cols.map(c=>'"'+String(d[c]??'').replaceAll('"','""')+'"').join(','))];let a=document.createElement('a');let u=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=u;a.download=`mcube-dids-${type}.csv`;a.click();URL.revokeObjectURL(u)}
</script>
<svelte:head><title>MCube | DID Number Management</title><meta name="description" content="MCube DID management workspace"/></svelte:head>
{#if !token}
 <main class="login auth-layout">
  <aside class="auth-hero" aria-label="MCube DID Manager welcome">
   <div class="auth-hero-pattern" aria-hidden="true"><span></span><span></span><span></span><span></span></div>
   <div class="auth-hero-content">
    <div class="auth-spark" aria-hidden="true">✳</div>
    <h1>Hello<br/>MCube! <span class="auth-wave" aria-hidden="true">👋</span></h1>
    <p>Manage DID assignments, review replacement requests and keep your calling operations running smoothly.</p>
   </div>
   <div class="auth-hero-footer">© {new Date().getFullYear()} MCube DID Manager. All rights reserved.</div>
  </aside>
  <section class="auth-form-side">
   <div class="auth-form-wrap">
    <div class="auth-wordmark"><span class="auth-wordmark-icon">▦</span><span>MCube <b>DID Manager</b></span></div>
    <form class="login-card auth-card" onsubmit={e=>{e.preventDefault();challengeId?verifyOtp():signin()}}>
     <div class="auth-form-heading">
      {#if challengeId}
       <button type="button" class="auth-back" aria-label="Back to sign in" title="Back to sign in" onclick={()=>{challengeId='';loginOtp='';loginError=''}}><ArrowLeft size={19}/></button>
       <div class="auth-step-icon"><ShieldCheck size={23}/></div>
       <h2>Verify your email</h2>
       <p>Enter the 6-digit verification code sent to <strong>{loginEmail}</strong>. The code expires in 5 minutes.</p>
      {:else}
       <h2>Welcome back!</h2>
       <p>Sign in securely to your operations workspace.</p>
      {/if}
     </div>
     {#if !challengeId}
      <div class="auth-field"><label for="auth-email">Work email</label><div class="auth-input-wrap"><Mail size={19}/><input id="auth-email" type="email" bind:value={loginEmail} placeholder="name@company.com" required autocomplete="username"/></div></div>
      <div class="auth-field"><label for="auth-pin">Security PIN</label><div class="auth-input-wrap"><LockKeyhole size={19}/><input id="auth-pin" type={showLoginPin?'text':'password'} inputmode="numeric" minlength="4" maxlength="12" bind:value={loginPin} placeholder="Enter your PIN" required autocomplete="current-password"/><button type="button" class="auth-eye" aria-label={showLoginPin?'Hide PIN':'Show PIN'} onclick={()=>showLoginPin=!showLoginPin}>{#if showLoginPin}<EyeOff size={18}/>{:else}<Eye size={18}/>{/if}</button></div></div>
     {:else}
      <div class="auth-field"><label for="auth-otp">Verification code</label><div class="auth-input-wrap auth-otp-wrap"><ShieldCheck size={19}/><input id="auth-otp" type="text" inputmode="numeric" maxlength="6" bind:value={loginOtp} oninput={(e)=>{loginOtp=e.currentTarget.value.replace(/\D/g,'').slice(0,6)}} placeholder="000000" required autocomplete="one-time-code"/></div></div>
     {/if}
     {#if loginError}<div class="auth-error" role="alert"><AlertCircle size={17}/><span>{loginError}</span></div>{/if}
     <button class="auth-submit" disabled={loginBusy} type="submit">{#if loginBusy}<RefreshCw size={18} class="spin"/>{:else}<span>{challengeId?'Verify & sign in':'Continue securely'}</span><ArrowRight size={19}/>{/if}</button>
     <div class="auth-footnote"><ShieldCheck size={15}/> Protected with PIN and email verification</div>
    </form>
   </div>
  </section>
 </main>
{:else}
 <div class="app"><header class="topbar"><div class="brand"><span class="brand-mark">▦</span><span>MCube <b>DID Manager</b></span></div><nav>{#each [{name:'Dashboard',icon:LayoutDashboard},{name:'Analytics',icon:ChartNoAxesColumn},{name:'Request',icon:FilePlus2},{name:'Report',icon:FileText},...(role==='admin'?[{name:'Settings',icon:FileText}]:[])] as n}<button class:current={tab===n.name} disabled={batchBusy} onclick={()=>openTab(n.name)}><n.icon size={18}/>{n.name}</button>{/each}</nav><div class="profile-wrap"><button class="profile-trigger" disabled={batchBusy} onclick={()=>profileOpen=!profileOpen} aria-label="Open account menu"><span class="profile-avatar">{role==='admin'?'A':'O'}</span><span class="profile-text">{role==='admin'?'Administrator':'Operator'}</span><span>⌄</span></button>{#if profileOpen}<div class="profile-menu"><strong>MCube workspace</strong><small>{role==='admin'?'Administrator access':'Operator access'}</small><button onclick={()=>{profileOpen=false;openTab('Settings')}}>Settings</button><button onclick={()=>{profileOpen=false;signout()}}><LogOut size={15}/> Sign out</button></div>{/if}</div></header>
 <main class="container"><div class="workspace-heading"><div><span class="workspace-eyebrow">MCUBE / OPERATIONS CENTER</span><h1>{tab==='Request'?'Replacement requests':tab==='Dashboard'?'DID inventory':tab==='Analytics'?'Operations analytics':tab==='Report'?'Quality & performance reports':'Workspace settings'}</h1><p>{tab==='Request'?'Review inbound requests, monitor exceptions and approve safe DID replacements.':tab==='Dashboard'?'Live inventory, assignment health and controlled replacement operations.':tab==='Analytics'?'Explore trends, turnaround times and repeat behavior.':tab==='Report'?'Team performance and exportable QC intelligence.':'Manage integrations, sync schedules and application rules.'}</p></div><div class="workspace-chip"><span class="live-dot"></span> Operations workspace <span class="workspace-tz">· IST</span></div></div>
 {#if error}<div class="message error"><AlertCircle size={17}/>{error}<button onclick={()=>error=''}><X size={16}/></button></div>{/if}
 {#if notice}<div class="message success"><CheckCircle2 size={17}/>{notice}<button onclick={()=>notice=''}><X size={16}/></button></div>{/if}

 {#if tab==='Dashboard'}
 {#if inventoryStatus && !inventoryStatus.initialized && tab==='Dashboard'}
 <section class="setup-banner"><div><strong>First-time setup: DID inventory has not been imported</strong><p>Your Google Sheet is empty. Import active, inactive and pool DIDs from MCube before using the replacement queue. This only reads MCube and saves inventory snapshots; it does not replace DIDs or initiate calls.</p></div><button class="primary" disabled={loading||initialSyncBusy||batchBusy} onclick={initializeInventory}>{initialSyncBusy?'Importing inventory…':'Import MCube DID inventory'}</button></section>
{:else if inventoryStatus?.initialized && tab==='Dashboard'}
 <div class="sync-caption">Last successful MCube inventory import: {formatIST(inventoryStatus.last_sync_utc)} · Active {inventoryStatus.counts?.active??0} · Inactive {inventoryStatus.counts?.inactive??0} · Pool {inventoryStatus.counts?.pool??0}</div>
{/if}
<div class="metrics"><div class="metric"><span>Total DIDs</span><strong>{categoryItems.length.toLocaleString()}</strong></div>{#if type==='active' || type==='all'}<div class="metric"><span>Counsellors</span><strong>{counsellors.toLocaleString()}</strong></div><div class="metric"><span>Common Pool (active response)</span><strong>{activeCommonPool.toLocaleString()}</strong></div>{/if}<div class="metric"><span>Filtered Results</span><strong>{filtered.length.toLocaleString()}</strong></div></div>
 <section class="filters"><label class="search-field">Search<div class="input-icon"><Search size={19}/><input bind:value={query} oninput={()=>page=1} placeholder={type==='active'?'DID, agent, mobile or operator':'DID number or operator'}/></div></label><label>DID Type<select bind:value={type} onchange={()=>{page=1;assignment='all';operator='all';selectedDids=[]}}><option value="active">Active</option><option value="inactive">Inactive</option><option value="pool">Pool</option></select></label>{#if type==='active'}<label>Assignment<select bind:value={assignment} onchange={()=>page=1}><option value="all">All DIDs</option><option value="assigned">Assigned</option><option value="unassigned">Unassigned</option></select></label><label>Operator<select bind:value={operator} onchange={()=>page=1}><option value="all">All operators</option>{#each operators as o}<option value={o}>{o}</option>{/each}</select></label>{/if}<button class="primary export" onclick={exportCSV}><Download size={17}/> Download CSV</button></section>
 {#if type==='active'}<div class="selection-bar"><div class="selection-info"><b>{selectedDids.length} selected</b><span>· {pool.length} available FIFO pool DIDs</span></div><div class="selection-actions"><button class="outline" disabled={batchBusy} onclick={selectAllEligible}>Select all eligible</button><button class="outline" disabled={batchBusy||!selectedDids.length} onclick={()=>selectedDids=[]}>Clear selection</button><button class="primary" disabled={batchBusy||!selectedDids.length||selectedDids.length>pool.length} onclick={()=>confirmBatch=true}>Reassign selected ({selectedDids.length})</button></div></div>{/if}
 <div class="result-bar"><span>{loading?'Loading DID records…':`${filtered.length.toLocaleString()} ${type} DID records displayed.`}</span><button class="outline" onclick={()=>refresh(true)} disabled={loading||batchBusy}><RefreshCw size={16} class={loading ? 'spin' : ''}/> Refresh</button></div>
 {#if duplicateGroups.length}<section class="duplicate-panel"><button class="outline" onclick={()=>showDuplicates=!showDuplicates}>{showDuplicates?'Hide':'Show'} duplicate DID numbers ({duplicateGroups.length})</button>{#if showDuplicates}<div class="duplicate-list"><table><thead><tr><th>Category</th><th>Duplicate DID number</th><th>Occurrences</th><th>Agent(s), if available</th></tr></thead><tbody>{#each duplicateGroups as item}<tr><td>{item.status}</td><td><strong>{item.did}</strong></td><td>{item.count}</td><td>{item.agents||'—'}</td></tr>{/each}</tbody></table></div>{/if}</section>{/if}
 {#if batchBusy}<div class="message success">Bulk reassignment running: {batch?.done||0} / {batch?.total||selectedDids.length}. Navigation and DID controls are locked until processing finishes. Keep this tab open.</div>{/if}
 {#if batchError}<div class="message error">{batchError}</div>{/if}
 {#if batch?.error}<div class="message error">Batch stopped: {batch.error}. Review Change_Logs before retrying.</div>{/if}
 {#if operationResults.length}<div class="operation-results"><b>Replacement results</b>{#each operationResults as result}<div class:result-failed={result.status!=='success'}><span>{result.old} → {result.new||'—'}</span><span class="pill {result.status==='success'?'pool':'inactive'}">{result.status==='success'?'Completed':result.status==='failed'?`Failed: ${result.stage||'operation'} · review required`:'Stopped · reconcile'}</span><small>{result.reason||''}</small></div>{/each}</div>{/if}
 <div class="table-card"><div class="table-scroll"><table><thead><tr>{#if type==='active'}<th><input aria-label="Select or unselect current page" type="checkbox" checked={allPageSelected} disabled={batchBusy} onchange={selectVisible}/></th>{/if}<th>SL. NO.</th><th>DID NUMBER</th>{#if type==='active'}<th>AGENT NAME</th><th>AGENT NUMBER</th>{/if}<th>OPERATOR</th><th>STATUS</th>{#if type==='active'}<th>ACTION</th>{/if}</tr></thead><tbody>{#each pageItems as d,i (`${d.status}-${d.did}-${(page-1)*inventoryPageSize+i}`)}<tr class:duplicate-row={d.duplicate}>{#if type==='active'}<td>{#if d.agent_number && !d.duplicate && d.agent?.toLowerCase()!=='common pool'}<input type="checkbox" checked={selectedDids.includes(d.did)} disabled={batchBusy||(!selectedDids.includes(d.did)&&selectedDids.length>=pool.length)} onchange={()=>toggleDid(d.did)}/>{/if}</td>{/if}<td>{(page-1)*inventoryPageSize+i+1}</td><td class="number">{d.did}{#if d.duplicate}<span class="duplicate-label" title="Repeated DID in this category">Duplicate</span>{/if}</td>{#if type==='active'}<td>{d.agent||'—'}</td><td>{d.agent_number||'—'}</td>{/if}<td>{d.operator||'—'}</td><td><span class="pill {d.status==='active'?(d.agent_number&&d.agent?.toLowerCase()!=='common pool'?'counsellor':'commonpool'):d.status}">{d.status==='active'?(d.agent_number&&d.agent?.toLowerCase()!=='common pool'?'Counsellors':'Common pool'):d.status==='pool'?'Pool':'Inactive'}</span></td>{#if type==='active'}<td>{#if d.agent_number && !d.duplicate && d.agent?.toLowerCase()!=='common pool'}<button class="action reassign-btn" disabled={batchBusy} onclick={()=>openSingle(d)}><RefreshCw size={15}/> Reassign</button>{/if}</td>{/if}</tr>{:else}<tr><td colspan={type==='active'?8:4} class="empty">{loading?'Loading…':'No DID records found.'}</td></tr>{/each}</tbody></table></div><div class="pagination"><span>Rows <select aria-label="DIDs per page" bind:value={inventoryPageSize} onchange={()=>page=1}><option value={10}>10</option><option value={25}>25</option><option value={50}>50</option><option value={100}>100</option></select> · Showing {filtered.length?((page-1)*inventoryPageSize+1):0}–{Math.min(page*inventoryPageSize,filtered.length)} of {filtered.length}</span><div><button class="outline" disabled={page===1} onclick={()=>page--}>Previous</button><span>Page {page} of {Math.max(1,Math.ceil(filtered.length/inventoryPageSize))}</span><button class="outline" disabled={page*inventoryPageSize>=filtered.length} onclick={()=>page++}>Next</button></div></div></div>
 {:else if tab==='Request'}
 <section class="request-toolbar"><div class="request-toolbar-label"><span class="toolbar-icon"><FilePlus2 size={20}/></span><div><h2>Request queue</h2><p>Track and act on incoming replacement requests</p></div></div><div class="request-toolbar-actions"><button class="primary" disabled={requestBusy||batchBusy} onclick={syncRequests}><RefreshCw size={16}/> {requestBusy?'Syncing…':'Sync calls'}</button><button class="outline" disabled={requestBusy||batchBusy} onclick={runReminders}>Check reminders</button><button class="outline" onclick={loadRequests}><RefreshCw size={16}/> Refresh</button></div></section>
 <div class="metrics"><div class="metric"><span>Pending / Approved</span><strong>{requests.filter(r=>['pending','approved'].includes(r.status)).length}</strong></div><div class="metric"><span>Recent repeat review</span><strong>{requests.filter(r=>r.status==='review_required').length}</strong></div><div class="metric"><span>Completed</span><strong>{requests.filter(r=>r.status==='completed').length}</strong></div><div class="metric"><span>Needs reconciliation</span><strong>{requests.filter(r=>r.status==='needs_reconciliation').length}</strong></div></div>
 <div class="grid-tools"><div class="grid-search"><Search size={17}/><input aria-label="Search requests" placeholder="Search agent, mobile, DID or status…" bind:value={requestSearch} oninput={()=>requestPage=1}/></div><select aria-label="Filter request status" bind:value={requestStatus} onchange={()=>requestPage=1}><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="review_required">Review required</option><option value="completed">Completed</option><option value="rejected">Rejected</option><option value="needs_reconciliation">Needs reconciliation</option></select><span>{requestFiltered.length} matching</span></div><div class="result-bar"><b>{chosenRequests.length} selected</b><button class="primary" disabled={batchBusy||!chosenRequests.length} onclick={()=>requestConfirm=true}>Replace selected (FIFO)</button></div>
 <div class="table-card"><div class="table-scroll"><table><thead><tr><th>Select</th><th>Agent</th><th>Mobile</th><th>Current DID</th><th>First call</th><th>Last call</th><th>Calls</th><th>Status</th><th>Action</th></tr></thead><tbody>{#each requestVisible as r (r.request_id)}<tr><td><input type="checkbox" disabled={batchBusy||!['pending','approved'].includes(r.status)} checked={chosenRequests.includes(r.request_id)} onchange={()=>chosenRequests=chosenRequests.includes(r.request_id)?chosenRequests.filter(x=>x!==r.request_id):[...chosenRequests,r.request_id]}/></td><td>{r.agent_name||'—'}</td><td>{r.agent_number}</td><td>{r.current_did}</td><td>{formatIST(r.first_call_utc)}</td><td>{formatIST(r.last_call_utc)}</td><td>{r.call_count}</td><td><span class="pill {r.status==='completed'?'active':r.recent_warning==='yes'?'inactive':'pool'}">{r.status}{r.recent_warning==='yes'?' · recent replacement':''}</span></td><td>{#if role==='admin' && ['pending','review_required'].includes(r.status)}<button class="action" disabled={batchBusy||requestBusy} onclick={()=>openReview(r,true)}>Approve</button><button class="action danger" disabled={batchBusy||requestBusy} onclick={()=>openReview(r,false)}>Reject</button>{/if}{#if ['pending','approved'].includes(r.status)}<button class="action reassign-btn" disabled={batchBusy||requestBusy} onclick={()=>{chosenRequests=[r.request_id];requestConfirm=true}}>Replace</button>{/if}</td></tr>{:else}<tr><td colspan="9">No requests yet. Sync inbound calls to import qualifying requests.</td></tr>{/each}</tbody></table></div><div class="pagination"><span>Rows <select aria-label="Requests per page" bind:value={requestPageSize} onchange={()=>requestPage=1}><option value={10}>10</option><option value={25}>25</option><option value={50}>50</option><option value={100}>100</option></select> · Showing {requestFiltered.length?(requestPage-1)*requestPageSize+1:0}–{Math.min(requestPage*requestPageSize,requestFiltered.length)} of {requestFiltered.length}</span><div><button class="outline" disabled={requestPage===1} onclick={()=>requestPage--}>Previous</button><span>Page {requestPage} of {Math.max(1,Math.ceil(requestFiltered.length/requestPageSize))}</span><button class="outline" disabled={requestPage*requestPageSize>=requestFiltered.length} onclick={()=>requestPage++}>Next</button></div></div></div>
 {#if duplicateGroups.length}<section class="duplicate-panel"><button class="outline" onclick={()=>showDuplicates=!showDuplicates}>{showDuplicates?'Hide':'Show'} duplicate DID numbers ({duplicateGroups.length})</button>{#if showDuplicates}<div class="duplicate-list"><table><thead><tr><th>Category</th><th>Duplicate DID number</th><th>Occurrences</th><th>Agent(s), if available</th></tr></thead><tbody>{#each duplicateGroups as item}<tr><td>{item.status}</td><td><strong>{item.did}</strong></td><td>{item.count}</td><td>{item.agents||'—'}</td></tr>{/each}</tbody></table></div>{/if}</section>{/if}
 {#if batchBusy}<div class="message success">Sequential replacement running. Do not initiate another batch.</div>{/if}
 {#if batchError}<div class="message error">{batchError}</div>{/if}
 {:else if tab==='Settings'}
 <div class="settings-header"><div><h1>Application settings</h1><p>Manage MCube connectivity, replacement rules and notifications. Changes are saved to Google Sheets only when you click Save.</p></div><div class="settings-actions"><button class="outline" disabled={saving} onclick={loadSettings}>Reload from Sheets</button>{#if role==='admin'}<button class="primary" disabled={saving||batchBusy||!settingsLoaded||!settingsDirty} onclick={saveSettings}>{saving?'Saving and verifying…':'Save changes'}</button>{/if}</div></div>
 {#if role!=='admin'}<div class="message error">Settings are read-only for operators.</div>{/if}
 {#if !settingsLoaded}<div class="message error">Settings have not loaded successfully. Do not edit or save until Google Sheets is accessible.</div>{/if}
 {#if settingsDirty}<div class="unsaved-indicator">You have unsaved changes. Reload discards them.</div>{/if}
 <div class="settings-workspace">
 <nav class="settings-nav" aria-label="Settings categories">
 {#each [{id:'intake',label:'Request intake'},{id:'credentials',label:'MCube login'},{id:'notifications',label:'Call notifications'},{id:'safety',label:'Replacement rules'},{id:'email',label:'Email'},{id:'employees',label:'Employee directory'},{id:'advanced',label:'Advanced'}] as section}
 <button type="button" class:active={settingsSection===section.id} onclick={()=>settingsSection=section.id}>{section.label}</button>
 {/each}
 </nav>
 <div class="settings-layout">
  {#if settingsSection==='credentials' && role==='admin'}<section class="settings-section"><div class="section-heading"><h2>MCube config portal login</h2><p>For inbound call logs and employee directory only. DID listing and replacement continue using the fixed REST bearer token.</p></div><div class="settings-fields"><label class="setting-field"><span>MCube username</span><input type="text" autocomplete="off" bind:value={mcubeUsername} placeholder="MCube portal username"/></label><label class="setting-field"><span>MCube password</span><input type="password" autocomplete="new-password" bind:value={mcubePassword} placeholder="Enter password to update"/></label></div><p>{mcubeCredentialConfigured?'Credentials saved (encrypted). Password is never displayed.':'Credentials not yet saved.'}</p>{#if mcubeCredentialMessage}<p aria-live="polite">{mcubeCredentialMessage}</p>{/if}<div class="settings-actions"><button class="primary" disabled={mcubeCredentialBusy||!mcubeUsername||!mcubePassword} onclick={saveMCubeCredentials}>{mcubeCredentialBusy?'Please wait…':'Save MCube login'}</button><button class="outline" disabled={mcubeCredentialBusy||!mcubeCredentialConfigured} onclick={testMCubeCredentials}>Test MCube login</button></div></section>{/if}
  {#if settingsSection==='intake'}<section class="settings-section"><div class="section-heading"><h2>MCube and request intake</h2><p>Numbers and call-log import behavior</p></div><div class="settings-fields">
  {#each [{key:'request_did',label:'Replacement request DID',hint:'Editable MCube filter-inbound DID; defaults to 8071439545 for new installations. Saved in Google Sheets.'},{key:'call_page_size',label:'Call-log page size',numeric:true,min:1},{key:'employee_refresh_hours',label:'Legacy employee refresh interval (hours)',numeric:true,min:1},{key:'auto_inventory_minutes',label:'Automatic DID inventory refresh (minutes)',numeric:true,min:1},{key:'auto_calls_minutes',label:'Automatic request-call sync (minutes)',numeric:true,min:1},{key:'auto_employee_minutes',label:'Automatic employee directory sync (minutes)',numeric:true,min:1},{key:'request_sync_lookback_minutes',label:'Call sync lookback (minutes)',numeric:true,min:1},{key:'recent_replacement_days',label:'Recent replacement warning (days)',numeric:true,min:1}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type={field.numeric?'number':'text'} min={field.min} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,field.numeric?Number(e.currentTarget.value):e.currentTarget.value)}/>{#if field.hint}<small>{field.hint}</small>{/if}</label>{/each}
  <label class="setting-field"><span>Request synchronization</span><select disabled={role!=='admin'||!settingsLoaded} value={settings.sync_mode||'manual'} onchange={e=>changeSetting('sync_mode',e.currentTarget.value)}><option value="manual">Manual only</option><option value="login">On application login</option></select></label>
  </div><p class="settings-help">Automatic sync runs when your external scheduler calls /api/maintenance/tick with MAINTENANCE_TOKEN. Configure cron-job.org every 5 minutes; each operation runs only when its saved interval is due. Reminders follow their existing settings. No browser needs to remain open.</p></section>{/if}
  {#if settingsSection==='safety'}<section class="settings-section"><div class="section-heading"><h2>Replacement safety</h2><p>Protect agents against accidental repeat replacements</p></div><div class="settings-toggle-list"><label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings.require_recent_review} onchange={e=>changeSetting('require_recent_review',e.currentTarget.checked)}/><span><b>Administrator review for recent replacements</b><small>Require approval for replacements within the configured warning period.</small></span></label></div></section>
  {/if}
  {#if settingsSection==='notifications'}<section class="settings-section"><div class="section-heading"><h2>Outbound call notifications</h2><p>MCube connects exenumber first, then custnumber. Level 1/2 numbers are saved in Google Sheets. Agent calls always use the verified MCube agent number as exenumber. Leave calling disabled until tested.</p></div><div class="settings-fields">
  {#each [{key:'level1_exenumber',label:'Level 1 exenumber (MCube registered agent mobile)'},{key:'level1_custnumber',label:'Level 1 custnumber (destination)'},{key:'level2_exenumber',label:'Level 2 exenumber (MCube registered agent mobile)'},{key:'level2_custnumber',label:'Level 2 custnumber (destination)'},{key:'agent_notification_custnumber',label:'Agent notification custnumber (defaults to request DID)'},{key:'reminder_first_minutes',label:'First reminder delay (minutes)',numeric:true},{key:'reminder_interval_minutes',label:'Repeat interval (minutes)',numeric:true},{key:'reminder_escalation_minutes',label:'Escalation delay (minutes)',numeric:true},{key:'reminder_max_attempts',label:'Maximum attempts',numeric:true}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type={field.numeric?'number':'text'} min={field.numeric?0:undefined} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,field.numeric?Number(e.currentTarget.value):e.currentTarget.value)}/></label>{/each}
  </div><div class="settings-toggle-list">{#each [{key:'reminder_enabled',label:'Enable periodic reminder calls'},{key:'notify_on_queue',label:'Call Level 1 on new queue entry'},{key:'notify_level2_on_queue',label:'Also call Level 2 on new queue entry'},{key:'notify_on_completion',label:'Call agent after replacement (agent mobile as exenumber)'}] as field}<label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings[field.key]} onchange={e=>changeSetting(field.key,e.currentTarget.checked)}/><span><b>{field.label}</b></span></label>{/each}</div></section>
  {/if}
  {#if settingsSection==='email'}<section class="settings-section"><div class="section-heading"><h2>Email and Brevo</h2><p>Brevo credentials remain private in Render environment variables</p></div><div class="settings-fields">{#each [{key:'admin_email',label:'Administrator notification email'},{key:'mail_from',label:'Notification sender address'}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type="email" value={settings[field.key]??''} oninput={e=>changeSetting(field.key,e.currentTarget.value)}/></label>{/each}<label class="setting-field"><span>Mail provider</span><select disabled={role!=='admin'||!settingsLoaded} value={settings.mail_provider||'disabled'} onchange={e=>changeSetting('mail_provider',e.currentTarget.value)}><option value="disabled">Disabled</option><option value="brevo">Brevo API</option></select></label></div><div class="settings-toggle-list">{#each [{key:'email_on_queue',label:'Email agent when queued'},{key:'email_on_completion',label:'Email agent when completed'}] as field}<label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings[field.key]} onchange={e=>changeSetting(field.key,e.currentTarget.checked)}/><span><b>{field.label}</b></span></label>{/each}</div></section>
  {/if}
  {#if settingsSection==='employees'}<section class="settings-section"><div class="section-heading"><h2>Employee directory</h2><p>Import minimal employee fields for request matching and email notifications</p></div><button class="outline" disabled={employeeSyncBusy||batchBusy} onclick={syncEmployees}>{employeeSyncBusy?'Refreshing employees…':'Refresh employee directory'}</button></section>{/if}
 {#if settingsSection==='advanced'}<section class="settings-section"><div class="section-heading"><h2>Advanced routing</h2><p>Legacy fallback numbers, saved in Google Sheets.</p></div><div class="settings-fields">{#each [{key:'first_contact_number',label:'Legacy first contact'},{key:'second_contact_number',label:'Legacy second contact'},{key:'outbound_caller_number',label:'Legacy outbound caller'}] as field}<label class="setting-field"><span>{field.label}</span><input type="tel" disabled={role!=='admin'||!settingsLoaded} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,e.currentTarget.value)}/></label>{/each}</div><p class="settings-help">Keep infrastructure secrets in Render environment variables, not GitHub or Google Sheets.</p></section>{/if}
 </div></div>
 <div class="settings-footer"><span>{settingsDirty?'Unsaved changes':'All loaded changes are saved'}</span>{#if role==='admin'}<button class="primary" disabled={saving||batchBusy||!settingsLoaded||!settingsDirty} onclick={saveSettings}>{saving?'Saving…':'Save changes to Google Sheets'}</button>{/if}</div>
 {:else if tab==='Analytics' || tab==='Report'}
 <section class="insights-page">
  <div class="insights-heading"><div><h2>{tab==='Analytics'?'Overview':'Reports'}</h2><p>Saved requests, employee directory and verified DID operations</p></div><button class="outline" disabled={insightsBusy} onclick={loadInsights}><RefreshCw size={16}/>{insightsBusy?'Loading…':'Refresh data'}</button></div>
  {#if insightsError}<div class="message error">{insightsError}</div>{/if}
  {#if insights}
  <div class="insight-kpis">{#each [{name:'Employees',value:insights.summary.employees},{name:'Requests',value:insights.summary.requests},{name:'Repeat employees',value:insights.summary.repeat_requests},{name:'Avg. turnaround',value:insights.summary.average_turnaround_hours===null?'—':`${insights.summary.average_turnaround_hours}h`},{name:'Median turnaround',value:insights.summary.median_turnaround_hours===null?'—':`${insights.summary.median_turnaround_hours}h`},{name:'Verified replacements',value:insights.summary.replacement_completions},{name:'Inbound call events',value:insights.summary.call_events},{name:'Audit events',value:insights.summary.audit_events}] as k}<div class="insight-kpi"><span>{k.name}</span><strong>{k.value.toLocaleString()}</strong></div>{/each}</div>
  {#if tab==='Analytics'}
  <div class="insight-grid"><section class="insight-panel"><h2>Request status</h2><p>Current workflow distribution</p>{#each Object.entries(insights.statuses).sort((a,b)=>b[1]-a[1]) as item}<div class="bar-row"><div><b>{item[0].replaceAll('_',' ')}</b><span>{item[1]}</span></div><div class="bar-track"><div class="bar-fill" style:width={`${100*item[1]/Math.max(1,insights.summary.requests)}%`}></div></div></div>{:else}<p>No requests recorded yet.</p>{/each}</section><section class="insight-panel"><h2>Requests over time</h2><p>Daily volume, based on first call date</p><div class="daily-bars">{#each insights.by_day.slice(-21) as day}<div class="daily-col" title={`${day.date}: ${day.requests} requests`}><span style:height={`${Math.max(4,100*day.requests/Math.max(1,...insights.by_day.map(x=>x.requests)))}%`}></span><small>{day.date.slice(5)}</small></div>{:else}<p>No daily activity yet.</p>{/each}</div></section></div>
  {/if}
  <section class="insight-panel"><div class="insight-section-heading"><div><h2>Monthly employee replacement requests</h2><p>One count per distinct request, not per inbound call. Filter by month or employee.</p></div><button class="outline" disabled={!monthlyAgents.length} onclick={()=>downloadReport(monthlyAgents,'monthly-employee-requests.csv')}><Download size={16}/> Export CSV</button></div><div class="grid-tools"><div class="grid-search"><Search size={17}/><input placeholder="Search agent, phone, manager or TL" bind:value={analyticsSearch} oninput={()=>analyticsPage=1}/></div><select bind:value={analyticsMonth} onchange={()=>analyticsPage=1}><option value="all">All months</option>{#each [...new Set(monthOptions)].sort().reverse() as month}<option value={month}>{month}</option>{/each}</select><select aria-label="Monthly rows per page" bind:value={analyticsPageSize} onchange={()=>analyticsPage=1}><option value={10}>10 rows</option><option value={25}>25 rows</option><option value={50}>50 rows</option><option value={100}>100 rows</option></select></div><div class="table-scroll"><table><thead><tr><th>Month</th><th>Employee</th><th>Mobile</th><th>Manager</th><th>Team lead</th><th>Requests</th><th>Inbound calls</th><th>Completed</th><th>Rejected</th></tr></thead><tbody>{#each monthlyAgents.slice((analyticsPage-1)*analyticsPageSize,analyticsPage*analyticsPageSize) as a}<tr><td>{a.month}</td><td><strong>{a.agent_name||'Unknown'}</strong></td><td>{a.agent_number}</td><td>{a.manager||'—'}</td><td>{a.team_lead||'—'}</td><td><strong>{a.requests}</strong></td><td>{a.calls}</td><td>{a.completed}</td><td>{a.rejected}</td></tr>{:else}<tr><td colspan="9">No matching monthly requests.</td></tr>{/each}</tbody></table></div><div class="pagination"><span>{monthlyAgents.length} records</span><div><button class="outline" disabled={analyticsPage===1} onclick={()=>analyticsPage--}>Previous</button><span>Page {analyticsPage} of {Math.max(1,Math.ceil(monthlyAgents.length/analyticsPageSize))}</span><button class="outline" disabled={analyticsPage*analyticsPageSize>=monthlyAgents.length} onclick={()=>analyticsPage++}>Next</button></div></div></section>
  <section class="insight-panel"><div class="insight-section-heading"><div><h2>Manager and team lead performance</h2><p>Requests grouped by MCube role5 (manager) and role4 (team lead)</p></div><button class="outline" onclick={()=>downloadReport(insights.teams,'manager-teamlead-report.csv')} disabled={!insights.teams.length}><Download size={16}/> Export CSV</button></div><div class="table-scroll"><table><thead><tr><th>Manager</th><th>Team lead</th><th>Employees</th><th>Requests</th><th>Repeat calls</th><th>Pending</th><th>Review</th><th>Completed</th><th>Repeat employees</th><th>Avg. resolution</th><th>Completion %</th></tr></thead><tbody>{#each insights.teams as t}<tr><td>{t.manager}</td><td>{t.team_lead}</td><td>{t.unique_employees}</td><td><strong>{t.requests}</strong></td><td>{t.repeat_calls}</td><td>{t.pending}</td><td>{t.review_required}</td><td>{t.completed}</td><td>{t.repeat_employee_count}</td><td>{t.average_turnaround_hours===null?'—':`${t.average_turnaround_hours}h`}</td><td>{t.completion_rate_pct}%</td></tr>{:else}<tr><td colspan="11">No requests available for reporting.</td></tr>{/each}</tbody></table></div></section>
  <section class="insight-panel"><div class="insight-section-heading"><div><h2>Employee request frequency</h2><p>Identify frequent requests and repeated calls</p></div><button class="outline" onclick={()=>downloadReport(insights.agents,'employee-request-frequency.csv')} disabled={!insights.agents.length}><Download size={16}/> Export CSV</button></div><input class="report-search" placeholder="Search employee, manager or team lead" bind:value={reportSearch}/><div class="table-scroll"><table><thead><tr><th>Employee</th><th>Mobile</th><th>Team lead</th><th>Manager</th><th>Requests</th><th>Calls</th><th>Completed</th><th>Median gap</th><th>Avg. resolution</th><th>Last replacement</th><th>Last request</th></tr></thead><tbody>{#each insights.agents.filter(a=>`${a.agent_name} ${a.agent_number} ${a.manager} ${a.team_lead}`.toLowerCase().includes(reportSearch.toLowerCase())).slice(0,250) as a}<tr><td>{a.agent_name||'Unknown'}</td><td>{a.agent_number}</td><td>{a.team_lead||'—'}</td><td>{a.manager||'—'}</td><td>{a.requests}</td><td>{a.calls}</td><td>{a.completed}</td><td>{a.median_days_between_requests===null?'—':`${a.median_days_between_requests}d`}</td><td>{a.average_turnaround_hours===null?'—':`${a.average_turnaround_hours}h`}</td><td>{a.last_replacement_utc?formatIST(a.last_replacement_utc):'—'}</td><td>{a.last_request_utc?formatIST(a.last_request_utc):'—'}</td></tr>{:else}<tr><td colspan="11">No matching employees.</td></tr>{/each}</tbody></table></div></section>
  <section class="insight-method"><strong>QC measurement rules</strong><span>Turnaround: first qualifying call → verified completion. Repeat requests: separate requests for the same employee; multiple cancelled calls within one request are tracked separately. Manager/TL reflects the current directory. Last call is not treated as a DID replacement.</span><small>{insights.summary.turnaround_sample_size} completed requests have valid turnaround timestamps.</small></section>
  {#if tab==='Report'}<section class="insight-panel"><div class="insight-section-heading"><div><h2>Recent DID operations</h2><p>Recorded audit events; only verified completion events count as successful replacements</p></div><button class="outline" onclick={()=>downloadReport(insights.recent_operations,'did-operation-audit.csv')} disabled={!insights.recent_operations.length}><Download size={16}/> Export CSV</button></div><div class="table-scroll"><table><thead><tr><th>Time</th><th>Event</th><th>Agent</th><th>Old DID</th><th>New DID</th><th>Result</th></tr></thead><tbody>{#each insights.recent_operations as e}<tr><td>{formatIST(e.time_utc)}</td><td>{e.event}</td><td>{e.agent_name||e.agent_number||'—'}</td><td>{e.old_did||'—'}</td><td>{e.new_did||'—'}</td><td>{e.result||'—'}</td></tr>{:else}<tr><td colspan="6">No audit history yet.</td></tr>{/each}</tbody></table></div></section>{/if}
  {:else if insightsBusy}<p>Loading saved operational data…</p>{/if}
 </section>
 {:else}<div class="placeholder"><h1>{tab}</h1><button class="outline" onclick={()=>tab='Dashboard'}>Back to Dashboard</button></div>{/if}
 </main></div>
{/if}
{#if reviewTarget}
 <div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!requestBusy)reviewTarget=null}}>
  <section class="modal single-modal" role="dialog" aria-modal="true" aria-label="Confirm request review">
   <button class="close" disabled={requestBusy} onclick={()=>reviewTarget=null}><X size={20}/></button>
   <h2>{reviewDecision?'Approve':'Reject'} replacement request?</h2>
   <p class="subtitle">This changes the request status only. It does not call MCube or replace a DID.</p>
   <div class="detail"><h3>REQUEST DETAILS</h3><div class="detail-grid"><span>Agent</span><b>{reviewTarget.agent_name||'—'}</b><span>Mobile</span><b>{reviewTarget.agent_number}</b><span>Current DID</span><b>{reviewTarget.current_did}</b><span>Calls</span><b>{reviewTarget.call_count}</b><span>Status</span><b>{reviewTarget.status}</b><span>Last call</span><b>{formatIST(reviewTarget.last_call_utc)}</b></div></div>
   <label class="date-field">Reason for {reviewDecision?'approval':'rejection'}<textarea rows="3" bind:value={reviewReason} placeholder="Enter reason" style="width:100%;min-height:76px;padding:12px;border:1px solid #ddd;border-radius:10px"></textarea></label>
   <div class="modal-actions"><button class="outline" disabled={requestBusy} onclick={()=>reviewTarget=null}>Cancel</button><button class:danger={!reviewDecision} class="primary" disabled={requestBusy||!reviewReason.trim()} onclick={confirmReview}>{requestBusy?'Saving…':reviewDecision?'Confirm approval':'Confirm rejection'}</button></div>
  </section>
 </div>
{/if}
{#if requestConfirm}
 <div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!batchBusy)requestConfirm=false}}>
  <section class="modal batch-modal" role="dialog" aria-modal="true" aria-label="Confirm request FIFO replacements">
   <button class="close" disabled={batchBusy} onclick={()=>requestConfirm=false}><X size={20}/></button>
   <h2>Confirm request replacements ({chosenRequests.length})</h2>
   <p class="subtitle">Review the requested replacements before starting sequential MCube operations. The server revalidates the current assignment and FIFO pool. This action can change live DIDs.</p>
   <div class="checkout-steps"><span class="checkout-step active">1 · Review requests</span><span class="checkout-step">2 · Verify FIFO</span><span class="checkout-step">3 · Confirm operation</span></div><div class="plan-scroll"><table class="plan-table"><thead><tr><th>Agent</th><th>Mobile</th><th>Current DID</th><th>Calls</th><th>Request status</th><th>Proposed FIFO DID</th></tr></thead><tbody>
    {#each chosenRequests as id,i}{@const r=requests.find(item=>item.request_id===id)}{#if r}<tr><td>{r.agent_name||'—'}</td><td>{r.agent_number}</td><td>{r.current_did}</td><td>{r.call_count}</td><td>{r.status}</td><td>{pool[i]?.did||'Not loaded — server determines FIFO'}</td></tr>{/if}{/each}
   </tbody></table></div>
   <p class="safety-note">FIFO values are illustrative only; server-side live verification is authoritative. If an operation is uncertain, do not repeat it until reconciled.</p>
   <div class="modal-actions"><button class="outline" onclick={()=>requestConfirm=false}>Cancel</button><button class="primary" disabled={batchBusy||!chosenRequests.length} onclick={replaceRequests}>Confirm & start {chosenRequests.length} replacements</button></div>
  </section>
 </div>
{/if}
{#if confirmBatch}<div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!batchBusy)confirmBatch=false}}><section class="modal batch-modal" role="dialog" aria-modal="true" aria-label="Confirm bulk reassignment"><button class="close" disabled={batchBusy} onclick={()=>confirmBatch=false}><X size={20}/></button><h2>Confirm bulk reassignment ({selectedDids.length})</h2><p class="subtitle">One agent at a time, in selection order. Old DID deactivation is followed by new DID activation and verification. Preview assignments may change if the live pool changes.</p><label class="date-field">Replacement request date<input type="date" bind:value={date}/></label><div class="plan-scroll"><table class="plan-table"><thead><tr><th>Agent</th><th>Agent number</th><th>Current DID</th><th>Operator</th><th>Proposed FIFO DID</th><th>New operator</th><th>Status</th></tr></thead><tbody>{#each batchPlan as row,i}<tr><td>{row.old?.agent||'—'}</td><td>{row.old?.agent_number||'—'}</td><td>{row.old?.did||'—'}</td><td>{row.old?.operator||'—'}</td><td>{row.next?.did||'Unavailable'}</td><td>{row.next?.operator||'—'}</td><td><span class="pill queued">Queued</span></td></tr>{/each}</tbody></table></div><p class="safety-note">If MCube rejects a deactivation, that record remains pending and the batch continues. Uncertain or partial changes stop the batch for administrator reconciliation.</p><div class="modal-actions"><button class="outline" onclick={()=>confirmBatch=false}>Cancel</button><button class="primary" disabled={batchBusy||selectedDids.length>pool.length} onclick={startBatch}>Deactivate & reassign {selectedDids.length}</button></div></section></div>{/if}
{#if selected && selected.action==='reassign'}<div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!batchBusy)selected=null}}><section class="modal single-modal" role="dialog" aria-modal="true" aria-label="Reassign DID"><button class="close" disabled={batchBusy} onclick={()=>selected=null}><X size={20}/></button><h2>Reassign DID</h2><p class="subtitle">Review the existing assignment and first available FIFO pool DID.</p><div class="detail"><h3>CURRENT ASSIGNMENT</h3><div class="detail-grid"><span>Agent</span><b>{selected.agent||'—'}</b><span>Agent number</span><b>{selected.agent_number||'—'}</b><span>Current DID</span><b>{selected.did}</b><span>Operator</span><b>{selected.operator||'—'}</b></div></div><div class="detail"><h3>NEW FIFO ASSIGNMENT</h3><div class="detail-grid"><span>New DID</span><b>{pool[0]?.did||'No pool DID available'}</b><span>New operator</span><b>{pool[0]?.operator||'—'}</b></div><label class="date-field">Replacement request date<input type="date" bind:value={date}/></label></div><p class="safety-note">The server rechecks live MCube assignments and FIFO availability before making changes. The proposed DID may change if another operator acts first.</p><div class="modal-actions"><button class="outline" onclick={()=>selected=null}>Cancel</button><button class="primary" disabled={batchBusy||!pool.length} onclick={confirmSingle}>Confirm reassignment</button></div></section></div>{/if}
